#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/badge/badge_values/badge_values.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// Badge's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/badge.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The number the badge shows in count mode; zero hides the chip unless show_zero is set.
template <typename Declaring>
struct BadgeCountCapability {
    PropertyCell<std::uint32_t, BadgeCountCapability<Declaring>> count{0U};

    static void assign(BadgeCountCapability& capability, std::uint32_t incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.count), incoming);
        if (!capability.count.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.count));
    }
};

// The largest count shown as it is (99 by default); a larger count shows the maximum followed by "+". Zero throws std::invalid_argument.
template <typename Declaring>
struct BadgeMaximumCapability {
    PropertyCell<std::uint32_t, BadgeMaximumCapability<Declaring>> maximum{99U};

    static void assign(BadgeMaximumCapability& capability, std::uint32_t incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.maximum), incoming);
        if (!capability.maximum.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.maximum));
    }
};

// Whether the badge shows a count chip or a dot without text.
template <typename Declaring>
struct BadgeModeCapability {
    PropertyCell<BadgeMode, BadgeModeCapability<Declaring>> mode{BadgeMode::count};

    static void assign(BadgeModeCapability& capability, BadgeMode incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.mode), incoming);
        if (!capability.mode.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.mode));
    }
};

// Whether a zero count still shows its chip; off by default.
template <typename Declaring>
struct BadgeShowZeroCapability {
    PropertyCell<bool, BadgeShowZeroCapability<Declaring>> show_zero{};

    static void assign(BadgeShowZeroCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.show_zero), incoming);
        if (!capability.show_zero.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.show_zero));
    }
};

// BadgeMode as a property value; defined beside Badge's table.
template <>
struct PropertyValueTraits<BadgeMode> {
    static PropertyType type();
    static BindingValue to_binding(BadgeMode value);
    static BadgeMode from_binding(const BindingValue& value);
};

// Every Badge capability, in the order the declaring class takes them.
template <typename Declaring>
struct BadgeCapabilities : public BadgeCountCapability<Declaring>,
                           public BadgeMaximumCapability<Declaring>,
                           public BadgeModeCapability<Declaring>,
                           public BadgeShowZeroCapability<Declaring> {};

} // namespace gui_forms
